<?php declare(strict_types=1);namespace App\Services;use App\Models\Coupon;final class CouponService{public static function validate(string $e,string $f):array{$p=Coupon::findByCode($e);if(!$p||!(int)$p['is_active']){return['coupon'=>null,'error'=>'coupon.invalid'];}$n=time();if($p['valid_from']&&strtotime($p['valid_from'])>$n){return['coupon'=>null,'error'=>'coupon.not_yet'];}if($p['valid_until']&&strtotime($p['valid_until'])<$n){return['coupon'=>null,'error'=>'coupon.expired'];}if($p['max_uses']!==null&&(int)$p['used']>=(int)$p['max_uses']){return['coupon'=>null,'error'=>'coupon.exhausted'];}if(!empty($p['plan_slugs'])&&!in_array($f,$p['plan_slugs'],true)){return['coupon'=>null,'error'=>'coupon.plan'];}return['coupon'=>$p,'error'=>null];}public static function discount(array $b,int $O):int{if($b['kind']==='percent'){return(int)round($O*min(100,max(0,(int)$b['value']))/100);}return min($O,max(0,(int)$b['value']));}public static function consume(array $i):void{\App\Core\DB::query('UPDATE {{coupons}} SET used = used + 1 WHERE id = ?',[(int)$i['id']]);}}